/*
 * Fondo blanco de controles: no hay token de blanco puro (§1.1);
 * --bw-surface-mist (#F8F9FB) es el neutro de superficie clara más cercano
 * al `white` del HTML aprobado (F-003).
 */

.page {
  min-width: 0;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin: 0 0 3px;
}

.subtitle {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  margin: 0 0 16px;
  max-width: 560px;
}

.e2eeBar {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--bw-signal-green);
  margin-bottom: 14px;
  padding: 6px 10px;
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
  width: fit-content;
}

.e2eeBar i {
  font-size: 12px;
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
}

.searchWrap i {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-size: 13px;
  color: var(--bw-input-text);
  outline: none;
  font-family: inherit;
  background: var(--bw-surface-mist);
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.primaryBtn {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-on-dark-hover); /* ≈ blanco: no hay token de blanco puro */
  font-size: 13px;
  font-weight: 500;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  opacity: 0.55;
  cursor: not-allowed;
}

.primaryBtn:disabled {
  cursor: not-allowed;
}

.actionHint {
  font-size: 12px;
  color: var(--bw-input-placeholder);
}

.threadCount {
  font-size: 12px;
  color: var(--bw-input-placeholder);
  margin-left: auto;
  white-space: nowrap;
}

.errorBanner {
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  color: var(--bw-sensitive-text);
  font-size: 13px;
  line-height: 1.5;
  padding: 12px 14px;
  border-radius: 5px;
  margin-bottom: 14px;
}

.loading {
  padding: 24px 0;
  font-size: 13px;
  color: var(--bw-steel-mist);
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-surface-mist);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  transition: all 0.12s;
}

.pageBtn:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled {
  color: var(--bw-input-placeholder);
  cursor: default;
}

.pageActive,
.pageActive:hover {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-on-dark-hover); /* ≈ blanco */
  cursor: default;
}

.pageEllipsis {
  min-width: 24px;
  text-align: center;
  font-size: 12px;
  color: var(--bw-steel-mist);
  user-select: none;
}

