import { useEffect, useState, type FormEvent } from 'react';
import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /**
   * Cableada por el shell desde `App.tsx` después de escribirse esta tarea
   * (F-118): se declara aquí porque es la firma pública del componente y sin
   * ella el repo no compila. MSG-02 no está en el alcance: la prop se recibe
   * y se ignora, no cambia nada de lo que hace esta pantalla.
   */
  onOpenThread?: (threadId: string) => void;
}

/**
 * El aviso de error enseña el error de verdad (F-128): PostgREST rechaza con un
 * objeto plano `{ code, message }`, así que `String(e)` daría `[object Object]`
 * y `e.message` daría `undefined`. Se sacan `code` y/o `message` cuando existan
 * y se pintan junto a la frase para humanos.
 */
function describeError(e: unknown): string {
  if (typeof e === 'object' && e !== null) {
    const candidate = e as { code?: unknown; message?: unknown };
    const code = typeof candidate.code === 'string' ? candidate.code : '';
    const message = typeof candidate.message === 'string' ? candidate.message : '';
    if (code || message) {
      return `No se pudieron cargar los hilos. ${[code, message]
        .filter(Boolean)
        .join(' ')}`.trim();
    }
  }
  if (e instanceof Error) {
    return `No se pudieron cargar los hilos. ${e.message}`;
  }
  return `No se pudieron cargar los hilos. ${String(e)}`;
}

/** Ventana de páginas para no pintar cien botones cuando el total crezca. */
function pagesToShow(current: number, total: number): (number | 'ellipsis')[] {
  if (total <= 7) {
    return Array.from({ length: total }, (_, i) => i + 1);
  }
  const out: (number | 'ellipsis')[] = [1];
  const start = Math.max(2, current - 1);
  const end = Math.min(total - 1, current + 1);
  if (start > 2) out.push('ellipsis');
  for (let i = start; i <= end; i += 1) out.push(i);
  if (end < total - 1) out.push('ellipsis');
  out.push(total);
  return out;
}

/**
 * Pantalla MSG-01 · Lista de Hilos.
 *
 * Es la pantalla, no un componente de presentación: posee el estado de
 * búsqueda y de página, y llama a `fetchThreadPage` con `profile.orgId`.
 */
export function Messages({ profile, now = new Date() }: MessagesProps) {
  const [input, setInput] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((result) => {
        if (cancelled) return;
        setThreads(result.threads);
        setTotal(result.total);
        setLoading(false);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setError(e);
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, search, page]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setPage(1);
    setSearch(input.trim());
  };

  const pages = pageCount(total);
  const canPrev = page > 1;
  const canNext = page < pages;

  return (
    <div className={styles.page}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado
        de extremo a extremo.
      </p>

      <div className={styles.e2eeBar}>
        <i className="ti ti-lock" aria-hidden="true" />
        E2EE activo · claves en memoria de sesión · contenido descifrado localmente
      </div>

      <form className={styles.actionsBar} onSubmit={handleSubmit}>
        <div className={styles.searchWrap}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            value={input}
            onChange={(e) => setInput(e.target.value)}
            aria-label="Buscar por nombre de organización"
          />
        </div>
        {/* DIR-01 no está entre las 8 pantallas del alcance (Plan §9): el control
            existe en el mock pero no lleva a ninguna parte — deshabilitado con el
            motivo visible, como el botón de subida de INV-01 (F-023 e).
            `aria-describedby` + `title` hacen que el motivo sea también parte de
            la descripción accesible del botón. */}
        <button
          type="button"
          className={styles.primaryBtn}
          disabled
          aria-describedby="msg01-nuevo-contacto-motivo"
          title="El Directorio queda fuera del MVP"
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span id="msg01-nuevo-contacto-motivo" className={styles.actionHint}>
          El Directorio queda fuera del MVP
        </span>
        <span className={styles.threadCount} data-testid="pag-info">
          {total.toLocaleString('es-ES')} {total === 1 ? 'hilo' : 'hilos'} · Página{' '}
          {page.toLocaleString('es-ES')} de {pages.toLocaleString('es-ES')}
        </span>
      </form>

      {/* F-127: el aviso de error lleva role="alert" — no sale gratis del HTML.
          F-128: enseña el error de verdad, no un "[object Object]" (F-020). */}
      {error ? (
        <div role="alert" className={styles.errorBanner}>
          {describeError(error)}
        </div>
      ) : null}

      {loading ? (
        <div className={styles.loading}>Cargando hilos…</div>
      ) : (
        <>
          <ThreadList
            threads={threads}
            now={now}
            onOpen={() => {
              // MSG-02 no está en el alcance: abrir un hilo no lleva a ningún
              // sitio. `onOpenThread` se declara en la firma pero se ignora.
            }}
          />
          {threads.length > 0 ? (
            <nav className={styles.pagination} aria-label="Paginación de hilos">
              <button
                type="button"
                className={styles.pageBtn}
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={!canPrev}
                aria-label="Página anterior"
              >
                ‹
              </button>
              {pagesToShow(page, pages).map((p, idx) =>
                p === 'ellipsis' ? (
                  <span key={`e-${idx}`} className={styles.pageEllipsis}>
                    …
                  </span>
                ) : (
                  <button
                    key={p}
                    type="button"
                    className={`${styles.pageBtn} ${p === page ? styles.pageActive : ''}`}
                    onClick={() => setPage(p)}
                    aria-current={p === page ? 'page' : undefined}
                  >
                    {p}
                  </button>
                ),
              )}
              <button
                type="button"
                className={styles.pageBtn}
                onClick={() => setPage((p) => Math.min(pages, p + 1))}
                disabled={!canNext}
                aria-label="Página siguiente"
              >
                ›
              </button>
            </nav>
          ) : null}
        </>
      )}
    </div>
  );
}

