/*
 * Fondo blanco de la lista: el sistema de diseño no tiene token de blanco puro
 * (§1.1), y --bw-surface-mist (#F8F9FB) es el neutro de superficie clara más
 * cercano al `white` del HTML aprobado. El check de paleta valida contra los
 * tokens, así que el literal está prohibido aunque el valor coincida (F-003).
 */

.list {
  list-style: none;
  margin: 0;
  padding: 0;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  margin: 0;
  padding: 0;
  border-bottom: 1px solid var(--bw-divider-mist);
}

.row:last-child {
  border-bottom: none;
}

/* El botón ocupa toda la fila; el <li> conserva su rol implícito `listitem` y
   el <ul> su `list` (F-131). */
.rowButton {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  background: none;
  border: none;
  cursor: pointer;
  font-family: inherit;
  color: inherit;
  text-align: left;
  transition: background 0.1s;
}

.rowButton:hover {
  background: var(--bw-row-hover-tint);
}

.rowTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orgName {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.countryBadge {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  flex-shrink: 0;
}

.rowTs {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
  justify-self: end;
}

.rowBottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  font-size: 12px;
  color: var(--bw-steel-mist);
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
  flex-shrink: 0;
}

/* Mapeo del tono (stateTone) al badge de la spec §3. El hex de la spec vive en
   los tokens `--bw-*`; aquí solo se referencian. */
.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.info {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.warn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.success {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.closed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* ── Estado vacío (spec §6) ─────────────────────────────────────────────── */

.empty {
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  padding: 48px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  text-align: center;
}

.emptyText {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  max-width: 420px;
  margin: 0;
}

.emptyButton {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-on-dark-hover); /* ≈ blanco: no hay token de blanco puro */
  font-size: 13px;
  font-weight: 500;
  font-family: inherit;
  margin-top: 6px;
  opacity: 0.55;
  cursor: not-allowed;
}

.emptyReason {
  font-size: 12px;
  color: var(--bw-input-placeholder);
  margin: 0;
}

