import {
  previewLabel,
  relativeTime,
  stateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /** Avisa con el ID del hilo, nunca con el objeto. */
  onOpen: (id: string) => void;
}

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Pinta las filas en el orden que recibe — el orden (actividad descendente) es
 * del servidor. No carga datos ni pagina: eso vive en `Messages`.
 *
 * Cada fila es un `<li>` con un `<button>` dentro. El `listitem` implícito del
 * `<li>` se conserva a propósito (F-131): poner `role="button"` encima lo
 * sustituiría y rompería la consulta por rol en los dos ficheros.
 */
export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.empty}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar
          con otras organizaciones.
        </p>
        {/* F-023 e / F-128: el botón "dice por qué" está deshabilitado — el
            Directorio queda fuera del MVP. `aria-describedby` y `title` hacen
            que el motivo sea parte de la descripción accesible. */}
        <button
          type="button"
          className={styles.emptyButton}
          disabled
          aria-describedby="msg01-vacio-motivo"
          title="El Directorio queda fuera del MVP"
        >
          Ir al Directorio
        </button>
        <p id="msg01-vacio-motivo" className={styles.emptyReason}>
          El Directorio queda fuera del MVP
        </p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => (
        <li key={thread.id} className={styles.row}>
          {/* El nombre accesible del botón es el de la contraparte, no todo el
              contenido de la fila: con 30 hilos, "Tarjeta de consulta · 6205-2RS"
              como nombre se repetiría y ninguna consulta por rol sería unívoca. */}
          <button
            type="button"
            className={styles.rowButton}
            aria-label={thread.counterpartyName}
            onClick={() => onOpen(thread.id)}
          >
            <span className={styles.rowTop}>
              <span className={styles.orgName}>{thread.counterpartyName}</span>
              {thread.counterpartyCountry ? (
                <span className={styles.countryBadge}>
                  {thread.counterpartyCountry}
                </span>
              ) : null}
            </span>
            <span className={styles.rowTs}>
              {relativeTime(thread.lastItemAt, now)}
            </span>
            <span className={styles.rowBottom}>
              <span className={styles.preview}>
                {previewLabel(thread.lastItem)}
              </span>
              <span
                className={`${styles.stateBadge} ${styles[stateTone(thread.state)]}`}
              >
                {thread.state}
              </span>
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}
